      "Προφύλαξη μετά από εκδορά ή αφαίρεση ξένου σώματος κερατοειδούς.",
      "Ενισχυμένα κολλύρια (αμινογλυκοσίδη μαζί με κεφαλοσπορίνη) στη βαριά βακτηριακή κερατίτιδα."
